// Generated by Go's png.Encoder and decoded again with image/png. Browsers
// tolerate corrupt zlib checksums; upload tests must use a strictly valid file.
export function localRedBackgroundPNG(): Buffer {
  return Buffer.from(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAAEUlEQVR4nAAEAPv/Av8AAAMAAwkBAvk/Y+MAAAAASUVORK5CYII=",
    "base64",
  );
}
